package com.example.audiobible.fragmentsimport android.Manifestimport android.content.pm.PackageManagerimport android.os.Buildimport android.os.Bundleimport android.view.Menuimport android.view.MenuInflaterimport android.view.MenuItemimport androidx.activity.viewModelsimport androidx.appcompat.app.AppCompatActivityimport androidx.core.view.MenuProviderimport androidx.navigation.fragment.NavHostFragmentimport com.example.audiobible.Rimport com.example.audiobible.databinding.ActivityAppBindingimport dagger.hilt.android.AndroidEntryPointimport ru.netology.mediapleer2.TrackViewModel@AndroidEntryPointclass AppActivity : AppCompatActivity() {    private val viewModel: TrackViewModel by viewModels()    private var isUserTrackingSeekBar = false    // 1. Делаем binding глобальным свойством класса    private lateinit var binding: ActivityAppBinding    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        // 2. Инициализируем binding (без ключевого слова val перед ним!)        binding = ActivityAppBinding.inflate(layoutInflater)        setContentView(binding.root)        // 3. Назначаем наш Toolbar главным для Activity        setSupportActionBar(binding.toolbar)        // 4. Находим навигационный контроллер        val navController = (supportFragmentManager.findFragmentById(binding.navMain.id) as NavHostFragment).navController        // 5. Запрашиваем разрешения        requestNotificationsPermission()        binding.toolbar.setNavigationOnClickListener {            onBackPressedDispatcher.onBackPressed()        }        // 6. Настраиваем меню        addMenuProvider(            object : MenuProvider {                override fun onCreateMenu(menu: Menu, menuInflater: MenuInflater) {                    menuInflater.inflate(R.menu.auth_menu, menu)                }                override fun onMenuItemSelected(menuItem: MenuItem): Boolean {                    return when (menuItem.itemId) {                        R.id.signin -> true                        R.id.signup -> {                            navController.navigate(R.id.action_feedFragment_to_fragmentChapter2)                            true                        }                        R.id.logout -> true                        else -> false                    }                }            }        )        if (savedInstanceState == null) {            viewModel.restoreLastGlobalTrack()        }    }    private fun requestNotificationsPermission() {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return        val permission = Manifest.permission.POST_NOTIFICATIONS        if (checkSelfPermission(permission) == PackageManager.PERMISSION_GRANTED) return        requestPermissions(arrayOf(permission), 1)    }    // Теперь функция работает без ошибок, так как binding доступен во всем классе    fun changeToolbar(title: String) {        supportActionBar?.setDisplayHomeAsUpEnabled(true)        binding.toolbar.title = title        val colorFrom = binding.toolbar.solidColor        val colorTo = android.graphics.Color.rgb((0..255).random(), (0..255).random(), (0..255).random())        android.animation.ValueAnimator.ofObject(android.animation.ArgbEvaluator(), colorFrom, colorTo).apply {            duration = 1000            addUpdateListener { animator ->                binding.toolbar.setBackgroundColor(animator.animatedValue as Int)            }            start()        }    }}